29	  messages: Message[];
30	  attachments: AttachmentInfo[];
31	  streamingMessageId: string | null;
32	  toolActivities: ToolActivityInfo[];
33	  builds: BuildInfo[];
34	  exportedCopies: ExportedCopyInfo[];
35	  physicalPrints: PhysicalPrintInfo[];
36	  changes: ChangeInfo[]; // already filtered to this conversation
37	  onRetry: (messageId: string) => void;
38	  onToolDecision: (actionId: string, decision: 'approve' | 'reject') => void;
39	  onToolCancel: (actionId: string) => void;
40	  // The setup card's expansion is a layer over this thread; the thread dims
41	  // rather than being covered, so the conversation stays legibly there.
42	  dimmed?: boolean;
43	  // The printer panel's own cards, each anchored after the message that drew
44	  // it, the way history entries are. Absent everywhere else.
45	  printerBlocks?: PrinterBlock[];
46	  onPrinterAction?: (
47	    action: 'network_pick' | 'candidate_pick' | 'add' | 'add_anyway' | 'reject' | 'browse' | 'manual_setup',
48	    id: string,
49	  ) => void;
50	  // "Answered · nothing changed" is about the open project, which the printer
51	  // panel is not having a conversation about.
52	  answeredState?: boolean;
