55	// What follows one conversation item: history cards and runs of changes, in
56	// seq order. Consecutive changes form one block, which draws as one group.
57	type TimelineBlock =
58	  | { kind: 'history'; seq: number; entry: ManufacturingHistoryEntry }
59	  | { kind: 'changes'; seq: number; changes: ChangeInfo[] };
60	
61	function timeline(history: ManufacturingHistoryEntry[], changes: ChangeInfo[]): TimelineBlock[] {
62	  const items = [
63	    ...history.map((entry) => ({ seq: entry.seq, history: entry, change: undefined })),
64	    ...changes.map((change) => ({ seq: change.seq, history: undefined, change })),
65	  ].sort((a, b) => a.seq - b.seq);
66	  const blocks: TimelineBlock[] = [];
67	  for (const item of items) {
68	    const previous = blocks[blocks.length - 1];
69	    if (item.change && previous?.kind === 'changes') previous.changes.push(item.change);
70	    else if (item.change) blocks.push({ kind: 'changes', seq: item.seq, changes: [item.change] });
71	    else blocks.push({ kind: 'history', seq: item.seq, entry: item.history! });
72	  }
73	  return blocks;
74	}
75	
76	function TimelineBlocks({ blocks }: { blocks: TimelineBlock[] }) {
77	  return (
78	    <>
79	      {blocks.map((block) =>
80	        block.kind === 'history' ? (
81	          <ManufacturingHistoryCard key={`${block.entry.kind}-${block.entry.record.id}`} entry={block.entry} />
82	        ) : (
83	          <ChangeRows key={`changes-${block.seq}`} changes={block.changes} />
84	        ),
85	      )}
86	    </>
87	  );
88	}
