108	}: Props) {
109	  const attachmentsById = new Map(attachments.map((attachment) => [attachment.id, attachment]));
110	  const listRef = useRef<HTMLDivElement>(null);
111	  const [followBottom, setFollowBottom] = useState(true);
112	
113	  const handleScroll = () => {
114	    const list = listRef.current;
115	    if (!list) return;
116	    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
117	    setFollowBottom(distanceFromBottom < 24);
