122	    if (list && followBottom) list.scrollTop = list.scrollHeight;
123	  }, [messages, toolActivities, builds, exportedCopies, physicalPrints, changes, printerBlocks, followBottom]);
124	
125	  const history: ManufacturingHistoryEntry[] = [
126	    ...builds.map((record) => ({ kind: 'build' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
127	    ...exportedCopies.map((record) => ({ kind: 'copy' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
128	    ...physicalPrints.map((record) => ({ kind: 'print' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
129	  ];
130	  const activitiesOf = (messageId: string) => toolActivities.filter((activity) => activity.correlationId === messageId);
131	  const plans = planMembers(toolActivities);
