      'hello_reject',
      'state',
      'projects',
      'printers',
      'appearance',
      'printer_error',
      'bridge_error',
      'printer_panel',
    ];
    expect([...page].sort()).toEqual([...protocolJson.pageMessageTypes].sort());
    expect([...host].sort()).toEqual([...protocolJson.hostMessageTypes].sort());
  });

