1	// Every word the printer panel shows the person, and the notes it records for
2	// the model after a tap. The app sends facts -- sizes, spools, which printer,
3	// what changed -- and the words are made here. The model's instructions are
4	// in printerInstructions.ts.
5	
6	import type {
7	  NetworkPrinterInfo,
8	  PrinterBlock,
9	  PrinterCardInfo,
10	  PrinterFacts,
11	  PrinterSessionPayload,
12	  PrinterSpoolInfo,
13	} from './bridge/protocol';
14	
15	// -- Numbers and lists --------------------------------------------------------
16	
17	// "0.4", "0.25", "1.0": two decimals, trailing zeros dropped down to one, as
18	// the printer profiles spell nozzle sizes.
19	export function numberText(value: number): string {
20	  let text = value.toFixed(2);
21	  while (text.length > 3 && text.endsWith('0')) text = text.slice(0, -1);
22	  return text;
23	}
24	
25	export function mm(value: number): string {
26	  return `${numberText(value)} mm`;
27	}
28	
29	// "a, b and c"
30	export function listed(items: string[]): string {
31	  return items.map((item, index) => (index === 0 ? '' : index + 1 === items.length ? ' and ' : ', ') + item).join('');
32	}
33	
34	// "0.2, 0.4, 0.6 and 0.8 mm"
35	export function sizesText(nozzles: number[]): string {
36	  return `${listed(nozzles.map(numberText))} mm`;
37	}
38	
39	function spoolName(spool: PrinterSpoolInfo): string {
40	  return spool.name || spool.material;
41	}
42	
43	// "PLA Matte and PETG", or "none"
44	function spoolsText(spools: PrinterSpoolInfo[]): string {
45	  return spools.length === 0 ? 'none' : listed(spools.map(spoolName));
46	}
47	
48	// What a printer has loaded, as one line: "AMS lite · PLA Matte + 3".
49	export function spoolSummary(ams: string, spools: PrinterSpoolInfo[]): string {
50	  if (spools.length === 0) return ams;
51	  const first = spoolName(spools[0]) + (spools.length > 1 ? ` + ${spools.length - 1}` : '');
52	  return ams ? `${ams} · ${first}` : first;
53	}
54	
55	// -- The panel's fixed words --------------------------------------------------
56	
57	export function caption(session: PrinterSessionPayload): string {
58	  return session.mode === 'add' ? 'NEW PRINTER' : 'PRINTER';
59	}
60	
61	// A likely answer, rather than a standing invitation.
62	export function placeholder(session: PrinterSessionPayload): string {
63	  return session.mode === 'add'
64	    ? 'e.g. "bambu a1 mini" or "not sure, the small one"'
65	    : 'e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"';
66	}
67	
68	export const ADD_LABEL = 'Add this printer';
69	export const REJECT_LABEL = 'Not this one';
70	
71	// The panel's own first line, which the model is shown as having said: the
72	// same promise every time the panel opens.
73	export function opening(session: PrinterSessionPayload): string {
74	  if (session.mode === 'change') {
75	    const name = session.context?.printer?.name || session.facts.printer.name || 'this printer';
76	    return `This is the ${name}. Tell me what changed on it, or ask anything about it: nozzle, plate, spools. A photo of the part works too.`;
77	  }
78	  return (
79	    "I'll add your printer so your projects slice for it. " +
80	    'What printer do you have? Say it any way: "bambu a1 mini", "the ender with the touchscreen", "not sure, the small one".'
81	  );
82	}
83	
84	// -- The pinned card ----------------------------------------------------------
85	
86	export interface FactText {
87	  value: string; // empty: nobody has said yet
88	  provenance: PrinterFacts['printer']['provenance'];
89	  swatch?: string;
90	}
91	
92	export function factTexts(facts: PrinterFacts): { printer: FactText; nozzle: FactText; plate: FactText; filament: FactText } {
93	  const loaded = facts.filament.spools;
94	  return {
95	    printer: { value: facts.printer.name, provenance: facts.printer.provenance },
96	    nozzle: { value: facts.nozzle.size > 0 ? mm(facts.nozzle.size) : '', provenance: facts.nozzle.provenance },
97	    plate: { value: facts.plate.name, provenance: facts.plate.provenance },
98	    filament: {
99	      value: loaded.length > 0 || facts.filament.ams ? spoolSummary(facts.filament.ams, loaded) : facts.filament.preset,
100	      provenance: facts.filament.provenance,
101	      swatch: loaded[0]?.colour || undefined,
102	    },
103	  };
104	}
105	
106	// -- The cards in the thread --------------------------------------------------
107	
108	// Under a printer's name: what the printer reported, or its size.
109	export function cardSubline(card: PrinterCardInfo): string {
110	  const device = card.device;
111	  if (!device) return card.buildVolume;
112	  let text = `${mm(device.nozzle)} nozzle`;
113	  if (device.spools.length > 0) text += ` · ${spoolSummary(device.ams, device.spools)}`;
114	  if (device.reported) text += ' · read from the printer just now';
115	  return text;
116	}
117	
118	// The undo row: "Nozzle set to 0.6 mm", "Spools updated", or both.
119	export function undoText(block: PrinterBlock): string {
120	  const parts: string[] = [];
121	  if (block.changed?.nozzle) parts.push(`Nozzle set to ${mm(block.changed.nozzle.after)}`);
122	  if (block.changed?.spools) parts.push(parts.length > 0 ? 'spools updated' : 'Spools updated');
123	  return parts.join(', ');
124	}
125	
126	// The change card's title.
127	export function changeTitle(nozzle: boolean, spools: boolean): string {
128	  return nozzle && spools ? 'Change nozzle and spools' : nozzle ? 'Change nozzle' : 'Change spools';
129	}
130	
131	// -- What the model is told after a tap ---------------------------------------
132	// Statements of what the person did, never instructions. The app posts them
133	// only when the tap goes through as described.
134	
135	export function rejectedNote(name: string): string {
136	  return `The person said ${name} is not their printer.`;
137	}
138	
139	export function chosenNote(card: PrinterCardInfo): string {
140	  const assumed = [`a ${mm(card.assumed.nozzle)} nozzle`];
141	  if (card.assumed.plate) assumed.push(`the ${card.assumed.plate}`);
142	  if (card.assumed.filament) assumed.push(card.assumed.filament);
143	  let text = `The person chose ${card.name}. Its card offers Add, assuming ${listed(assumed)}`;
144	  if (!card.assumed.plate) text += '; the profile names no plate';
145	  if (!card.assumed.filament) text += '; the profile names no filament';
146	  return `${text}.`;
147	}
148	
149	// For a network printer the app matched to a model in the list.
150	export function networkNote(printer: NetworkPrinterInfo): string {
151	  const match = printer.match;
152	  if (!match) return '';
153	  const start = `The person chose the network printer ${printer.serial}, a ${match.name}`;
154	  return match.reported
155	    ? `${start} that reports a ${mm(match.nozzle)} nozzle.`
156	    : `${start}; it did not report its nozzle, so its card assumes ${mm(match.nozzle)}.`;
157	}
158	
159	export function undoneNote(block: PrinterBlock): string {
160	  const back: string[] = [];
161	  if (block.changed?.nozzle) back.push(`the nozzle is ${mm(block.changed.nozzle.before)} again`);
162	  if (block.changed?.spools) back.push(`the spools are ${spoolsText(block.changed.spools.before)} again`);
163	  return `The person undid the change: ${listed(back)}.`;
164	}
165	
166	export const ACCESS_CODE_NOTE = 'An access code was entered.';

