// A small JPEG thumbnail of an image attachment, downscaled to
// kPreviewThumbnailEdge on its long edge regardless of the original's size
// or format, for the composer/thread preview only -- what reaches the model
// is the untouched original, read separately in printer_identify's own
// image context. Empty on anything wxImage cannot decode, or on the rare
// thumbnail that still exceeds kInlineImagePreviewCap.
std::string image_thumbnail_data_url(const std::string& bytes)
{
    wxMemoryInputStream input(bytes.data(), bytes.size());
    wxImage             image;
    if (!image.LoadFile(input, wxBITMAP_TYPE_ANY) || !image.IsOk())
        return {};
    const double scale = std::min(1.0, double(kPreviewThumbnailEdge) / std::max(image.GetWidth(), image.GetHeight()));
    if (scale < 1.0)
        image.Rescale(std::max(1, int(image.GetWidth() * scale)), std::max(1, int(image.GetHeight() * scale)),
                      wxIMAGE_QUALITY_HIGH);
    image.SetOption(wxIMAGE_OPTION_QUALITY, 85);
    wxMemoryOutputStream output;
    if (!image.SaveFile(output, wxBITMAP_TYPE_JPEG))
        return {};
    std::string encoded(output.GetSize(), '\0');
    output.CopyTo(encoded.data(), encoded.size());
    if (encoded.empty() || encoded.size() > kInlineImagePreviewCap)
        return {};
    return "data:image/jpeg;base64," + base64_encode(encoded);
}

